package awsconfig

import (
	"bytes"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	secretsmanager "github.com/aws/aws-sdk-go-v2/service/secretsmanager"
	"github.com/aws/aws-sdk-go-v2/service/secretsmanager/types"
	smithy "github.com/aws/smithy-go"
)

// Golden / equivalence test.
//
// testdata/golden_v1_3_0.json was generated by running this exact matrix against
// the UNMODIFIED v1.3.0 code (GOLDEN_UPDATE=1 go test ./config -run Golden). The
// matrix never sets a `secret` tag nor LoadOptions.RequireSecret, so every row
// must stay byte-identical after the secret:"only" / RequireSecret changes.
// Regenerating the file is only legitimate when intentionally changing v1.3.0
// behavior, which is out of scope for additive releases.

type goldenRecord struct {
	Case   string          `json:"case"`
	Result json.RawMessage `json:"result,omitempty"`
	Error  string          `json:"error,omitempty"`
	Kind   string          `json:"kind,omitempty"`
	Calls  int             `json:"fetchCalls"`
}

// goldenValidated is a Validator type (custom Validate replaces required checks).
type goldenValidated struct {
	Name string `json:"NAME" env:"NAME"`
	Env  string `json:"ENVIRONMENT" env:"ENVIRONMENT"`
}

func (g *goldenValidated) Validate() error {
	if g.Name == "" {
		return errors.New("name required")
	}
	return nil
}

// goldenKeys lists every key any matrix struct reads, so env can be fully
// controlled per case.
var goldenKeys = []string{
	"MONGO_URI", "MONGO_DB", "CACHE_ADDR", "POSTGRES_DSN", "AWS_REGION", "ENVIRONMENT",
	"CONSUMER_NAME", "MAX_RETRIES", "APP_DOMAIN", "APP_DOWNLOAD_LINK",
	"PRIMARY_IMG_CDN", "BACKUP_IMG_CDN", "PRIMARY_VID_CDN", "BACKUP_VID_CDN",
	"SERVER_PORT", "DEBUG", "TIMEOUT", "NAME",
}

type goldenType struct {
	name string
	load func(opts LoadOptions) (any, error)
}

func goldenTypes() []goldenType {
	wrap := func(v any, err error) (any, error) { return v, err }
	return []goldenType{
		{"core", func(o LoadOptions) (any, error) { return wrap(Load[CoreConfig]("sn", o)) }},
		{"streams", func(o LoadOptions) (any, error) { return wrap(Load[StreamsConfig]("sn", o)) }},
		{"web", func(o LoadOptions) (any, error) { return wrap(Load[WebConfig]("sn", o)) }},
		{"media", func(o LoadOptions) (any, error) { return wrap(Load[MediaConfig]("sn", o)) }},
		{"required", func(o LoadOptions) (any, error) { return wrap(Load[precConfig]("sn", o)) }},
		{"validator", func(o LoadOptions) (any, error) { return wrap(Load[goldenValidated]("sn", o)) }},
	}
}

const goldenFileBody = "MONGO_URI=file-uri\nMONGO_DB=file-db\nCACHE_ADDR=file-cache\nAWS_REGION=file-region\n" +
	"ENVIRONMENT=file-env\nCONSUMER_NAME=file-consumer\nMAX_RETRIES=2\nAPP_DOMAIN=file.example\n" +
	"PRIMARY_IMG_CDN=file-img\nPRIMARY_VID_CDN=file-vid\nSERVER_PORT=:1111\nDEBUG=false\nTIMEOUT=1s\nNAME=file-name\n"

var goldenEnvVars = map[string]string{
	"MONGO_URI": "env-uri", "ENVIRONMENT": "env-env", "CONSUMER_NAME": "env-consumer",
	"MAX_RETRIES": "7", "APP_DOMAIN": "env.example", "SERVER_PORT": ":2222", "NAME": "env-name",
	"DEBUG": "true", "TIMEOUT": "5s",
}

const goldenFullSecret = `{"MONGO_URI":"sec-uri","MONGO_DB":"sec-db","CACHE_ADDR":"sec-cache","AWS_REGION":"sec-region",` +
	`"ENVIRONMENT":"sec-env","CONSUMER_NAME":"sec-consumer","MAX_RETRIES":"9","APP_DOMAIN":"sec.example",` +
	`"PRIMARY_IMG_CDN":"sec-img","PRIMARY_VID_CDN":"sec-vid","SERVER_PORT":":3333","DEBUG":false,"TIMEOUT":"3s","NAME":"sec-name"}`

type goldenSecretCase struct {
	name string
	out  string // body ("" with err set means error case)
	err  error
	nilS bool
}

func goldenSecretCases() []goldenSecretCase {
	return []goldenSecretCase{
		{name: "full", out: goldenFullSecret},
		{name: "partial", out: `{"MONGO_URI":"sec-uri","ENVIRONMENT":"sec-env"}`},
		{name: "empty-object", out: `{}`},
		{name: "json-null-body", out: `null`},
		{name: "null-and-empty-values", out: `{"ENVIRONMENT":null,"MONGO_DB":"","NAME":null}`},
		{name: "not-found", err: &types.ResourceNotFoundException{}},
		{name: "access-denied", err: &smithy.GenericAPIError{Code: "AccessDeniedException", Message: "x"}},
		{name: "transient", err: errors.New("boom")},
		{name: "malformed", out: `not json`},
		{name: "empty-string-body", out: ``},
		{name: "array-body", out: `[]`},
		{name: "non-scalar-value", out: `{"MONGO_URI":{"a":1}}`},
		{name: "bad-int", out: `{"MAX_RETRIES":"abc"}`},
		{name: "nil-secret-string", nilS: true},
	}
}

func goldenKind(err error) string {
	switch {
	case err == nil:
		return ""
	case errors.Is(err, errSecretNotFound):
		return "notfound"
	case errors.Is(err, errSecretAccessDenied):
		return "denied"
	case errors.Is(err, errSecretTransient):
		return "transient"
	case errors.Is(err, errSecretMalformed):
		return "malformed"
	default:
		return "other"
	}
}

func goldenClearEnv(t *testing.T) {
	t.Helper()
	for _, k := range goldenKeys {
		t.Setenv(k, "") // registers restore of the original value
		os.Unsetenv(k)
	}
}

func buildGoldenMatrix(t *testing.T) []goldenRecord {
	t.Helper()
	prevDelay := retryBaseDelay
	retryBaseDelay = time.Millisecond
	defer func() { retryBaseDelay = prevDelay }()

	tmp := t.TempDir()
	filePath := filepath.Join(tmp, "present.env")
	if err := os.WriteFile(filePath, []byte(goldenFileBody), 0o600); err != nil {
		t.Fatal(err)
	}
	missingPath := filepath.Join(tmp, "missing.env")

	var recs []goldenRecord
	record := func(name string, res any, err error, calls int) {
		r := goldenRecord{Case: name, Kind: goldenKind(err), Calls: calls}
		if err != nil {
			r.Error = strings.ReplaceAll(err.Error(), tmp, "<TMP>")
		} else {
			b, mErr := json.Marshal(res)
			if mErr != nil {
				t.Fatal(mErr)
			}
			r.Result = b
		}
		recs = append(recs, r)
	}

	type layer struct {
		name string
		path string
		env  bool
	}
	layers := []layer{
		{"file-only", filePath, false},
		{"env-only", missingPath, true},
		{"file+env", filePath, true},
		{"none", missingPath, false},
	}

	for _, gt := range goldenTypes() {
		for _, ly := range layers {
			setup := func() {
				goldenClearEnv(t)
				if ly.env {
					for k, v := range goldenEnvVars {
						os.Setenv(k, v)
					}
				}
			}

			// (a) legacy, ForceLocal. Legacy's godotenv.Load mutates os.Environ,
			// so env is cleared again afterwards.
			setup()
			res, err := gt.load(LoadOptions{ForceLocal: true, LocalPath: ly.path})
			record("legacy-forcelocal/"+gt.name+"/"+ly.name, res, err, 0)
			goldenClearEnv(t)

			// (b) per-field, ForceLocal: AWS must never be called.
			setup()
			fake := &fakeFetcher{err: errors.New("must not be called")}
			restore := withFakeClient(t, fake)
			res, err = gt.load(LoadOptions{Precedence: PrecedenceSecretOverEnvOverFile, ForceLocal: true, LocalPath: ly.path})
			restore()
			record("perfield-forcelocal/"+gt.name+"/"+ly.name, res, err, fake.calls)

			// (c) per-field with a fake secret.
			for _, sc := range goldenSecretCases() {
				setup()
				f := &fakeFetcher{err: sc.err}
				switch {
				case sc.nilS:
					f.out = &secretsmanager.GetSecretValueOutput{}
				case sc.err == nil:
					f.out = secretOutput(sc.out)
				}
				restore := withFakeClient(t, f)
				res, err := gt.load(LoadOptions{Precedence: PrecedenceSecretOverEnvOverFile, LocalPath: ly.path})
				restore()
				record("perfield-secret/"+sc.name+"/"+gt.name+"/"+ly.name, res, err, f.calls)
			}
		}
	}
	return recs
}

func TestGolden_V1_3_0_Equivalence(t *testing.T) {
	recs := buildGoldenMatrix(t)
	got, err := json.MarshalIndent(recs, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	got = append(got, '\n')

	path := filepath.Join("testdata", "golden_v1_3_0.json")
	if os.Getenv("GOLDEN_UPDATE") == "1" {
		if err := os.MkdirAll("testdata", 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, got, 0o644); err != nil {
			t.Fatal(err)
		}
		t.Logf("wrote %d records to %s", len(recs), path)
		return
	}

	want, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read golden: %v", err)
	}
	if bytes.Equal(want, got) {
		return
	}
	// Report the first differing record.
	var wantRecs []goldenRecord
	if err := json.Unmarshal(want, &wantRecs); err != nil {
		t.Fatalf("parse golden: %v", err)
	}
	if len(wantRecs) != len(recs) {
		t.Fatalf("record count: want %d got %d", len(wantRecs), len(recs))
	}
	for i := range recs {
		a, _ := json.Marshal(wantRecs[i])
		b, _ := json.Marshal(recs[i])
		if !bytes.Equal(a, b) {
			t.Fatalf("v1.3.0 behavior changed for %q\nwant: %s\n got: %s", recs[i].Case, a, b)
		}
	}
	t.Fatal("golden bytes differ")
}
